// Agent 1: Data Parser (v2.0.1 — handles webhook body and direct test input)
const raw = $input.first().json;
const payload = raw.body || raw;

const context = {
  system_id: payload.system_id || `SYS-${Date.now()}`,
  domain: payload.domain || 'healthcare',
  timestamp: new Date().toISOString(),
  constraints: payload.constraints || { budget_usd: 100000, max_downtime_hrs: 40 },
  inputs: {
    tls_config: payload.tls_config || null,
    iot_traffic: payload.iot_traffic || null,
    ehr_records: payload.ehr_records || null,
    ai_prompt_logs: payload.ai_prompt_logs || null,
    device_logs: payload.device_logs || null
  },
  findings: [],
  metadata: {
    parser_version: '2.0.1',
    input_source: raw.body ? 'webhook_body' : 'direct_json',
    input_types_detected: []
  }
};

for (const [k, v] of Object.entries(context.inputs)) {
  if (v !== null && v !== undefined) context.metadata.input_types_detected.push(k);
}

return { json: context };

// Agent 2: Crypto Inventory Agent
const ctx = $input.first().json;
const tls = ctx.inputs.tls_config;
const findings = [];
const CLASSICAL = ['RSA', 'ECC', 'ECDSA', 'ECDH', 'ECDHE', 'DH', 'DHE', 'RSA-PSS', 'RSA-PKCS1'];
const DEPRECATED_TLS = ['TLS1.0', 'TLS1.1'];
const WEAK_HASH = ['SHA-1', 'MD5'];
const PQ = ['ML-KEM', 'ML-DSA', 'SLH-DSA', 'FN-DSA'];
if (tls) {
  if (tls.tls_version && DEPRECATED_TLS.includes(tls.tls_version)) {
    findings.push({ agent: 'crypto_inventory', severity: 'critical', type: 'deprecated_tls_version',
      detail: `${tls.tls_version} deprecated since 2020 (RFC 8996)`, detected_value: tls.tls_version,
      tippss_mapping: ['Security', 'Protection'] });
  }
  if (tls.key_exchange) {
    const ke = tls.key_exchange.toUpperCase();
    const isClass = CLASSICAL.some(a => ke.includes(a));
    const isPQ = PQ.some(a => ke.includes(a));
    if (isClass && !isPQ) {
      findings.push({ agent: 'crypto_inventory', severity: 'high', type: 'classical_key_exchange',
        detail: `${tls.key_exchange} key exchange not PQ safe`, detected_value: tls.key_exchange,
        tippss_mapping: ['Security', 'Protection'] });
    }
  }
  if (tls.cert_signature_algo) {
    const sig = tls.cert_signature_algo.toUpperCase();
    const isClass = CLASSICAL.some(a => sig.includes(a));
    const isPQ = PQ.some(a => sig.includes(a));
    if (isClass && !isPQ) {
      findings.push({ agent: 'crypto_inventory', severity: 'high', type: 'classical_signature',
        detail: `${tls.cert_signature_algo} certificate signature not PQ safe`, detected_value: tls.cert_signature_algo,
        tippss_mapping: ['Security', 'Identity', 'Protection'] });
    }
  }
  if (tls.hash && WEAK_HASH.includes(tls.hash)) {
    findings.push({ agent: 'crypto_inventory', severity: 'critical', type: 'weak_hash',
      detail: `${tls.hash} collision-vulnerable`, detected_value: tls.hash,
      tippss_mapping: ['Security', 'Protection'] });
  }
}
ctx.findings.push(...findings);
return { json: ctx };

// Agent 3: PQ Benchmark Agent
const ctx = $input.first().json;
const tls = ctx.inputs.tls_config;
const PQ_REC = {
  'RSA': { rec: 'ML-KEM-768 (FIPS 203) + ML-DSA-65 (FIPS 204)', priority: 'high' },
  'ECDH': { rec: 'ML-KEM-768 (FIPS 203) hybrid first', priority: 'high' },
  'ECDHE': { rec: 'X25519+ML-KEM-768 hybrid then full ML-KEM-768', priority: 'high' },
  'ECDSA': { rec: 'ML-DSA-65 (FIPS 204) hybrid first', priority: 'high' },
  'ECC': { rec: 'ML-KEM-768 + ML-DSA-65', priority: 'high' }
};
const pq_findings = [];
const classical = ctx.findings.filter(f => f.agent === 'crypto_inventory' 
  && f.type !== 'weak_hash' && f.type !== 'deprecated_tls_version');
for (const f of classical) {
  const algo = Object.keys(PQ_REC).find(a => f.detected_value && f.detected_value.toUpperCase().includes(a));
  if (algo) {
    pq_findings.push({ agent: 'pq_benchmark', severity: 'high', type: 'pq_migration_required',
      detail: `${algo} vulnerable to Shor's algorithm`, detected_algorithm: algo,
      recommendation: PQ_REC[algo].rec, priority: PQ_REC[algo].priority,
      tippss_mapping: ['Security', 'Protection'] });
  }
}
if (tls && tls.data_lifetime_years && tls.data_lifetime_years >= 10) {
  pq_findings.push({ agent: 'pq_benchmark', severity: 'critical', type: 'long_lifetime_classical_crypto',
    detail: `${tls.data_lifetime_years}-year lifetime + classical crypto = severe harvest-now-decrypt-later exposure`,
    tippss_mapping: ['Privacy', 'Protection', 'Security'] });
}
ctx.findings.push(...pq_findings);
return { json: ctx };

// Agent 4: Clinical Privacy Agent
const ctx = $input.first().json;
const prompts = ctx.inputs.ai_prompt_logs || [];
const PHI = [
  { rx: /\bMRN[:\s-]*\d{4,}/gi, type: 'medical_record_number' },
  { rx: /\b\d{3}-\d{2}-\d{4}\b/g, type: 'ssn' },
  { rx: /\bpatient\s+(name|id)[:\s]+[A-Z][a-z]+/gi, type: 'patient_identifier' },
  { rx: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, type: 'email' },
  { rx: /\b(HIV|AIDS|cancer|psychiatric|substance abuse)\s+(diagnosis|status|treatment|history)/gi, type: 'sensitive_diagnosis' }
];
const pf = [];
const arr = Array.isArray(prompts) ? prompts : [prompts];
for (let i = 0; i < arr.length; i++) {
  const p = arr[i]; if (!p) continue;
  const text = typeof p === 'string' ? p : (p.prompt || p.text || JSON.stringify(p));
  for (const pat of PHI) {
    const m = text.match(pat.rx);
    if (m) pf.push({ agent: 'clinical_privacy', severity: pat.type === 'sensitive_diagnosis' ? 'critical' : 'high',
      type: pat.type, detail: `PHI detected in prompt #${i}: ${pat.type}`, match_count: m.length,
      tippss_mapping: ['Privacy', 'Protection', 'Trust'] });
  }
}
ctx.findings.push(...pf);
return { json: ctx };

// Agent 5: Device Identity Agent
const ctx = $input.first().json;
const devices = ctx.inputs.device_logs || [];
const f = [];
const arr = Array.isArray(devices) ? devices : [devices];
for (const d of arr) {
  if (!d || typeof d !== 'object') continue;
  if (d.cert_present === false || d.certificate === null) {
    f.push({ agent: 'device_identity', severity: 'high', type: 'missing_certificate',
      detail: `Device ${d.device_id || 'unknown'} has no certificate`, device_id: d.device_id,
      tippss_mapping: ['Identity', 'Security'] });
  }
  if (d.auth_status === 'failed') {
    f.push({ agent: 'device_identity', severity: 'critical', type: 'authentication_failed',
      detail: `Device ${d.device_id || 'unknown'} authentication failed`, device_id: d.device_id,
      tippss_mapping: ['Identity', 'Safety'] });
  }
}
ctx.findings.push(...f);
return { json: ctx };

// Agent 6: Prompt Injection Agent
const ctx = $input.first().json;
const prompts = ctx.inputs.ai_prompt_logs || [];
const INJ = [
  { rx: /ignore\s+(all\s+)?(previous|prior|above)\s+(instructions|prompts|rules)/i, type: 'instruction_override', sev: 'critical' },
  { rx: /(you are now|switch to|enable)\s+(admin|dan|developer|jailbreak)\s*(mode)?/i, type: 'role_manipulation', sev: 'critical' },
  { rx: /(repeat|show|reveal|print)\s+(your|the)\s+(system|initial|original)\s+prompt/i, type: 'system_prompt_extraction', sev: 'high' },
  { rx: /\[(system|admin|override|approved)[^\]]*\]/i, type: 'fake_system_message', sev: 'critical' },
  { rx: /(authentication|consent|hipaa|authorization)\s+(has been|is)\s+(waived|bypassed|completed)/i, type: 'fake_authorization', sev: 'critical' }
];
const f = [];
const arr = Array.isArray(prompts) ? prompts : [prompts];
for (let i = 0; i < arr.length; i++) {
  const p = arr[i]; if (!p) continue;
  const text = typeof p === 'string' ? p : (p.prompt || p.text || '');
  for (const pat of INJ) {
    if (pat.rx.test(text)) f.push({ agent: 'prompt_injection', severity: pat.sev, type: pat.type,
      detail: `Prompt injection in #${i}: ${pat.type}`, tippss_mapping: ['Safety', 'Security', 'Trust'] });
  }
}
ctx.findings.push(...f);
return { json: ctx };

// Agent 7: Secret Exposure Agent
const ctx = $input.first().json;
const logs = ctx.inputs.device_logs || [];
const prompts = ctx.inputs.ai_prompt_logs || [];
const PAT = [
  { rx: /sk[-_]live[-_][A-Za-z0-9]{20,}/g, type: 'stripe_live_key', sev: 'critical' },
  { rx: /AKIA[0-9A-Z]{16}/g, type: 'aws_access_key', sev: 'critical' },
  { rx: /AIza[0-9A-Za-z\-_]{35}/g, type: 'google_api_key', sev: 'critical' },
  { rx: /Bearer\s+[A-Za-z0-9._\-+/]+={0,2}/g, type: 'bearer_token', sev: 'high' },
  { rx: /-----BEGIN (RSA |EC |DSA )?PRIVATE KEY-----/g, type: 'private_key', sev: 'critical' }
];
const f = [];
const text = [...(Array.isArray(logs) ? logs : [logs]), ...(Array.isArray(prompts) ? prompts : [prompts])]
  .map(x => typeof x === 'string' ? x : JSON.stringify(x || {})).join('\n');
for (const pat of PAT) {
  const m = text.match(pat.rx);
  if (m) f.push({ agent: 'secret_exposure', severity: pat.sev, type: pat.type,
    detail: `Exposed ${pat.type} (${m.length}x)`, match_count: m.length,
    tippss_mapping: ['Protection', 'Security'] });
}
ctx.findings.push(...f);
return { json: ctx };

// Agent 8: Safety Risk Agent
const ctx = $input.first().json;
const prompts = ctx.inputs.ai_prompt_logs || [];
const UNSAFE = [
  { rx: /(prescribe|administer|inject|give)\s+\d+\s*(mg|ml|mcg|units?)\s+(of\s+)?[a-z]+/i, type: 'autonomous_dosing', sev: 'critical' },
  { rx: /(auto[-_]?discharge|automatically discharge|discharge\s+without)/i, type: 'autonomous_discharge', sev: 'critical' },
  { rx: /(don'?t wait for|skip|bypass)\s+(physician|doctor|clinician|nurse)\s+(sign[-\s]?off|approval|review)/i, type: 'clinician_bypass', sev: 'critical' },
  { rx: /(override|silence|disable)\s+(the\s+)?(alarm|alert|warning)/i, type: 'alarm_override', sev: 'critical' },
  { rx: /(disclose|share|send|email)\s+(patient|clinical|medical)\s+(record|data|info|details)\s+to/i, type: 'unauthorized_disclosure', sev: 'critical' }
];
const f = [];
const arr = Array.isArray(prompts) ? prompts : [prompts];
for (let i = 0; i < arr.length; i++) {
  const p = arr[i]; if (!p) continue;
  const text = typeof p === 'string' ? p : (p.prompt || p.text || '');
  for (const pat of UNSAFE) {
    if (pat.rx.test(text)) f.push({ agent: 'safety_risk', severity: pat.sev, type: pat.type,
      detail: `Unsafe pattern in #${i}: ${pat.type}`, tippss_mapping: ['Safety', 'Trust'] });
  }
}
ctx.findings.push(...f);
return { json: ctx };

// Agent 9: TIPPSS Mapping Agent
const ctx = $input.first().json;
const pillars = {
  Trust: { score: 100, findings: [] },
  Identity: { score: 100, findings: [] },
  Privacy: { score: 100, findings: [] },
  Protection: { score: 100, findings: [] },
  Safety: { score: 100, findings: [] },
  Security: { score: 100, findings: [] }
};
const DEDUCT = { critical: 25, high: 15, medium: 8, low: 3 };
for (const f of ctx.findings) {
  const ded = DEDUCT[f.severity] || 5;
  for (const p of (f.tippss_mapping || [])) {
    if (pillars[p]) {
      pillars[p].findings.push(f);
      pillars[p].score = Math.max(0, pillars[p].score - ded);
    }
  }
}
ctx.tippss = pillars;
return { json: ctx };

// Scoring Engine — weighted PQ Risk Score 0-100
const ctx = $input.first().json;
const W = { pkc: 0.30, tls: 0.20, lifetime: 0.20, identity: 0.15, secrets: 0.10, migration: 0.05 };
const PTS = { critical: 100, high: 75, medium: 50, low: 25 };
const cat = { pkc: 0, tls: 0, lifetime: 0, identity: 0, secrets: 0, migration: 0 };
for (const f of ctx.findings) {
  const p = PTS[f.severity] || 25;
  if (f.agent === 'crypto_inventory' && f.type === 'deprecated_tls_version') cat.tls = Math.max(cat.tls, p);
  else if (f.agent === 'pq_benchmark' && f.type === 'long_lifetime_classical_crypto') cat.lifetime = Math.max(cat.lifetime, p);
  else if (f.agent === 'pq_benchmark' || f.agent === 'crypto_inventory') cat.pkc = Math.max(cat.pkc, p);
  else if (f.agent === 'device_identity') cat.identity = Math.max(cat.identity, p);
  else if (f.agent === 'secret_exposure') cat.secrets = Math.max(cat.secrets, p);
}
const tls = ctx.inputs.tls_config;
const pqDetected = tls && ((tls.key_exchange && /ML-KEM|ML-DSA|SLH-DSA/.test(tls.key_exchange))
  || (tls.cert_signature_algo && /ML-DSA|SLH-DSA|FN-DSA/.test(tls.cert_signature_algo)));
cat.migration = pqDetected ? 0 : 75;
let score = 0;
for (const k of Object.keys(W)) score += cat[k] * W[k];
score = Math.round(score);
let status;
if (score <= 25) status = 'Safe';
else if (score <= 50) status = 'Partially Safe';
else if (score <= 75) status = 'Not Post-Quantum Safe';
else status = 'Critical Quantum Risk';
ctx.scoring = { pq_risk_score: score, status, category_breakdown: cat, weights: W, tippss_scores: ctx.tippss };
return { json: ctx };

// =====================================================================
// AGENT 10: QIRO — Quantum-Inspired Remediation Optimizer
// =====================================================================
// Converts TIPPSS-mapped findings into a constrained binary optimization
// problem. Uses CPU-based simulated annealing (Ising/QUBO-style energy
// minimization) to find the best remediation portfolio under hospital
// budget and downtime constraints.
//
// NOT actual quantum hardware. NOT QPU. Pure JavaScript on CPU.
// =====================================================================
const ctx = $input.first().json;
const constraints = ctx.constraints || { budget_usd: 100000, max_downtime_hrs: 40 };

// ------------------------------------------------------------------
// Step 1: Convert findings into candidate remediation actions
// ------------------------------------------------------------------
const ACTION_TEMPLATES = {
  'classical_key_exchange':       { cost: 25000, downtime: 6,  complexity: 7, base_risk_reduction: 30 },
  'classical_signature':          { cost: 20000, downtime: 4,  complexity: 6, base_risk_reduction: 30 },
  'deprecated_tls_version':       { cost: 30000, downtime: 8,  complexity: 8, base_risk_reduction: 35 },
  'weak_hash':                    { cost: 22000, downtime: 5,  complexity: 6, base_risk_reduction: 30 },
  'pq_migration_required':        { cost: 50000, downtime: 12, complexity: 9, base_risk_reduction: 45 },
  'long_lifetime_classical_crypto': { cost: 45000, downtime: 10, complexity: 8, base_risk_reduction: 40 },
  'medical_record_number':        { cost: 8000,  downtime: 1,  complexity: 3, base_risk_reduction: 25 },
  'sensitive_diagnosis':          { cost: 12000, downtime: 2,  complexity: 4, base_risk_reduction: 35 },
  'patient_identifier':           { cost: 8000,  downtime: 1,  complexity: 3, base_risk_reduction: 22 },
  'missing_certificate':          { cost: 15000, downtime: 4,  complexity: 5, base_risk_reduction: 25 },
  'authentication_failed':        { cost: 10000, downtime: 2,  complexity: 4, base_risk_reduction: 35 },
  'instruction_override':         { cost: 8000,  downtime: 1,  complexity: 3, base_risk_reduction: 25 },
  'role_manipulation':            { cost: 8000,  downtime: 1,  complexity: 3, base_risk_reduction: 25 },
  'system_prompt_extraction':     { cost: 6000,  downtime: 1,  complexity: 2, base_risk_reduction: 18 },
  'fake_system_message':          { cost: 8000,  downtime: 1,  complexity: 3, base_risk_reduction: 25 },
  'fake_authorization':           { cost: 8000,  downtime: 1,  complexity: 3, base_risk_reduction: 28 },
  'stripe_live_key':              { cost: 5000,  downtime: 1,  complexity: 2, base_risk_reduction: 30 },
  'aws_access_key':               { cost: 5000,  downtime: 1,  complexity: 2, base_risk_reduction: 30 },
  'google_api_key':               { cost: 5000,  downtime: 1,  complexity: 2, base_risk_reduction: 28 },
  'bearer_token':                 { cost: 4000,  downtime: 1,  complexity: 2, base_risk_reduction: 22 },
  'private_key':                  { cost: 8000,  downtime: 2,  complexity: 3, base_risk_reduction: 35 },
  'autonomous_dosing':            { cost: 15000, downtime: 2,  complexity: 5, base_risk_reduction: 40 },
  'autonomous_discharge':         { cost: 12000, downtime: 2,  complexity: 4, base_risk_reduction: 35 },
  'clinician_bypass':             { cost: 12000, downtime: 2,  complexity: 4, base_risk_reduction: 35 },
  'alarm_override':               { cost: 15000, downtime: 3,  complexity: 5, base_risk_reduction: 40 },
  'unauthorized_disclosure':      { cost: 15000, downtime: 2,  complexity: 4, base_risk_reduction: 38 }
};

const SEV_MULT = { critical: 1.5, high: 1.0, medium: 0.6, low: 0.3 };
const PILLAR_WEIGHTS = { Trust: 1.0, Identity: 1.0, Privacy: 1.2, Protection: 1.0, Safety: 1.4, Security: 1.0 };

const actions = ctx.findings.map((f, idx) => {
  const tmpl = ACTION_TEMPLATES[f.type] || { cost: 10000, downtime: 2, complexity: 4, base_risk_reduction: 20 };
  const sevMult = SEV_MULT[f.severity] || 0.5;
  const pillars = f.tippss_mapping || [];
  const tippssWeight = pillars.reduce((s, p) => s + (PILLAR_WEIGHTS[p] || 1), 0);
  const isPQ = f.agent === 'pq_benchmark' || f.type === 'classical_key_exchange'
            || f.type === 'classical_signature' || f.type === 'long_lifetime_classical_crypto';
  const isSafety = pillars.includes('Safety');
  return {
    id: `A${idx + 1}`,
    finding_index: idx,
    finding_type: f.type,
    severity: f.severity,
    description: f.detail,
    risk_reduction: Math.round(tmpl.base_risk_reduction * sevMult),
    cost_usd: tmpl.cost,
    downtime_hrs: tmpl.downtime,
    complexity: tmpl.complexity,
    pqc_urgency: isPQ ? 25 : 0,
    safety_criticality: isSafety ? 20 : 0,
    tippss_weight: Math.round(tippssWeight * 10),
    tippss_pillars: pillars
  };
});

if (actions.length === 0) {
  ctx.qiro = { selected_actions: [], total_cost: 0, total_downtime: 0, total_risk_reduction: 0,
    status: 'no_actions_needed', message: 'No remediation actions required (system clean).' };
  return { json: ctx };
}

// ------------------------------------------------------------------
// Step 2: Define energy (objective) function
// ------------------------------------------------------------------
// Maximize: risk_reduction + pqc_urgency + tippss_weight + safety_criticality
// Minimize: cost (scaled), downtime, complexity
// Penalty: exceeding budget or downtime constraint
function evaluate(selection, actions, budget, maxDowntime) {
  let totalCost = 0, totalDowntime = 0, totalBenefit = 0, totalPenalty = 0;
  for (let i = 0; i < selection.length; i++) {
    if (selection[i] === 1) {
      const a = actions[i];
      totalCost += a.cost_usd;
      totalDowntime += a.downtime_hrs;
      totalBenefit += a.risk_reduction + a.pqc_urgency + a.safety_criticality + a.tippss_weight;
      totalPenalty += a.complexity * 0.5;
    }
  }
  let constraintPenalty = 0;
  if (totalCost > budget) constraintPenalty += (totalCost - budget) / 1000 * 10;
  if (totalDowntime > maxDowntime) constraintPenalty += (totalDowntime - maxDowntime) * 10;
  return totalBenefit - totalPenalty - constraintPenalty;
}

// ------------------------------------------------------------------
// Step 3: Simulated annealing
// ------------------------------------------------------------------
const N = actions.length;
const iterations = Math.min(2000, 100 + N * 50);
let T = 100.0;
const cooling = 0.995;

// Initialize: greedy start (select high-value low-cost actions)
let current = new Array(N).fill(0);
const sortedIdx = [...Array(N).keys()].sort((a, b) => {
  const sa = (actions[a].risk_reduction + actions[a].pqc_urgency + actions[a].safety_criticality) / Math.max(1, actions[a].cost_usd / 5000);
  const sb = (actions[b].risk_reduction + actions[b].pqc_urgency + actions[b].safety_criticality) / Math.max(1, actions[b].cost_usd / 5000);
  return sb - sa;
});
let runningCost = 0, runningDowntime = 0;
for (const i of sortedIdx) {
  if (runningCost + actions[i].cost_usd <= constraints.budget_usd
    && runningDowntime + actions[i].downtime_hrs <= constraints.max_downtime_hrs) {
    current[i] = 1;
    runningCost += actions[i].cost_usd;
    runningDowntime += actions[i].downtime_hrs;
  }
}
let currentScore = evaluate(current, actions, constraints.budget_usd, constraints.max_downtime_hrs);
let best = [...current], bestScore = currentScore;

// Main SA loop
for (let iter = 0; iter < iterations; iter++) {
  const idx = Math.floor(Math.random() * N);
  const neighbor = [...current];
  neighbor[idx] = 1 - neighbor[idx];
  const neighborScore = evaluate(neighbor, actions, constraints.budget_usd, constraints.max_downtime_hrs);
  const delta = neighborScore - currentScore;
  if (delta > 0 || Math.random() < Math.exp(delta / T)) {
    current = neighbor;
    currentScore = neighborScore;
    if (currentScore > bestScore) { best = [...current]; bestScore = currentScore; }
  }
  T *= cooling;
}

// ------------------------------------------------------------------
// Step 4: Build prioritized output
// ------------------------------------------------------------------
const selectedActions = [];
let totalCost = 0, totalDowntime = 0, totalRiskReduction = 0;
for (let i = 0; i < best.length; i++) {
  if (best[i] === 1) {
    selectedActions.push({ ...actions[i], priority_rank: selectedActions.length + 1 });
    totalCost += actions[i].cost_usd;
    totalDowntime += actions[i].downtime_hrs;
    totalRiskReduction += actions[i].risk_reduction;
  }
}
// Sort by combined urgency (PQC + safety + severity)
selectedActions.sort((a, b) => {
  const ua = a.pqc_urgency + a.safety_criticality + (SEV_MULT[a.severity] || 0.5) * 100;
  const ub = b.pqc_urgency + b.safety_criticality + (SEV_MULT[b.severity] || 0.5) * 100;
  return ub - ua;
});
selectedActions.forEach((a, i) => a.priority_rank = i + 1);

// Compute phase plan
const phases = {
  phase_1_immediate_0_6mo: selectedActions.filter(a => a.severity === 'critical' || a.pqc_urgency >= 25).slice(0, 5),
  phase_2_transitional_6_18mo: selectedActions.filter(a => a.severity === 'high' && a.pqc_urgency < 25),
  phase_3_full_pq_18_36mo: selectedActions.filter(a => a.severity !== 'critical' && a.severity !== 'high')
};

ctx.qiro = {
  algorithm: 'CPU-based Quantum-Inspired Simulated Annealing (Ising/QUBO-style)',
  iterations_run: iterations,
  final_temperature: T.toFixed(4),
  optimization_score: Math.round(bestScore),
  total_candidate_actions: N,
  selected_actions: selectedActions,
  selection_count: selectedActions.length,
  total_cost_usd: totalCost,
  total_downtime_hrs: totalDowntime,
  total_risk_reduction: totalRiskReduction,
  budget_constraint_usd: constraints.budget_usd,
  downtime_constraint_hrs: constraints.max_downtime_hrs,
  budget_utilization_pct: Math.round((totalCost / constraints.budget_usd) * 100),
  downtime_utilization_pct: Math.round((totalDowntime / constraints.max_downtime_hrs) * 100),
